begin;
select no_plan();
create temp table scoped_ids as select gen_random_uuid() artist, gen_random_uuid() owner, gen_random_uuid() event_id, gen_random_uuid() product, gen_random_uuid() pre, gen_random_uuid() post;
insert into auth.users(id,email) select owner,'summary-owner@example.test' from scoped_ids;
insert into public.artists(id,slug,display_name) select artist,'summary-scope-test','Summary scope' from scoped_ids;
insert into public.artist_members(artist_id,member_email,role,status) select artist,'summary-owner@example.test','owner','active' from scoped_ids;
insert into public.events(id,artist_id,event_name,start_date,end_date,status) select event_id,artist,'Scope event',now(),now()+interval '1 day','Confirmed' from scoped_ids;
insert into public.products(id,artist_id,name,price,status,currency) select product,artist,'Scoped product',100,'enable','THB' from scoped_ids;
insert into public.orders(id,event_id,order_type,customer_name,customer_email,pickup_code) select pre,event_id,'preorder','Test buyer','buyer@example.test',replace(gen_random_uuid()::text,'-','') from scoped_ids union all select post,event_id,'post_event','Test buyer','buyer@example.test',replace(gen_random_uuid()::text,'-','') from scoped_ids;
insert into public.order_items(order_id,product_id,quantity,price_per_unit) select pre,product,2,100 from scoped_ids union all select post,product,3,100 from scoped_ids;
insert into public.order_payments(order_id,event_id,artist_id,payment_status,amount_expected) select pre,event_id,artist,'payment_submitted',200 from scoped_ids union all select post,event_id,artist,'payment_confirmed',300 from scoped_ids;
select set_config('request.jwt.claims',jsonb_build_object('sub',owner,'email','summary-owner@example.test','role','authenticated')::text,true) from scoped_ids;
select is((select total_to_prepare from public.list_preorder_production_summary_scoped((select event_id from scoped_ids),'preorder')),2::bigint,'preorder quantity excludes post-event');
select is((select expected_amount from public.list_preorder_production_summary_scoped((select event_id from scoped_ids),'preorder')),200::numeric,'preorder amount excludes post-event');
select is((select total_to_prepare from public.list_preorder_production_summary_scoped((select event_id from scoped_ids),'post_event')),3::bigint,'post-event quantity excludes preorder');
select is((select confirmed_amount from public.list_preorder_production_summary_scoped((select event_id from scoped_ids),'post_event')),300::numeric,'post-event amount excludes preorder');
select throws_ok($$select * from public.list_preorder_production_summary_scoped((select event_id from scoped_ids),null)$$,'invalid_order_type','missing scope rejected');
select set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
select throws_ok($$select * from public.list_preorder_production_summary_scoped((select event_id from scoped_ids),'preorder')$$,'forbidden','unrelated user cannot read summary');
select * from finish();
rollback;
